package com.etendoerp.copilot.toolpack.tools;
import java.awt.image.BufferedImage;import java.nio.file.Path;import javax.enterprise.context.ApplicationScoped;import javax.inject.Named;import javax.imageio.ImageIO;import org.codehaus.jettison.json.JSONArray;import org.codehaus.jettison.json.JSONObject;import com.google.zxing.BinaryBitmap;import com.google.zxing.MultiFormatReader;import com.google.zxing.NotFoundException;import com.google.zxing.client.j2se.BufferedImageLuminanceSource;import com.google.zxing.multi.GenericMultipleBarcodeReader;import com.google.zxing.common.HybridBinarizer;import com.etendoerp.copilot.engine.tool.ServerTool;import com.etendoerp.copilot.engine.tool.ToolExecutionContext;import dev.langchain4j.agent.tool.ToolSpecification;
@ApplicationScoped @Named("CodbarTool") public class CodbarTool implements ServerTool{
 public String name(){return "CodbarTool";}public ToolSpecification specification(){return FileToolSupport.spec(name(),"This tool reads a barcode from image files. Receives filepath as an array of image paths and returns founded barcodes.","{\"filepath\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The paths of the image files to read.\"}}","filepath");}
 public String execute(JSONObject a,ToolExecutionContext c)throws Exception{JSONArray paths=a.optJSONArray("filepath");if(paths==null)throw new IllegalArgumentException("Expected 'filepath' to be a list of strings.");JSONArray result=new JSONArray();for(int i=0;i<paths.length();i++){Path path;try{path=FileToolSupport.readPath(c,paths.getString(i));}catch(java.io.FileNotFoundException e){continue;}BufferedImage image=ImageIO.read(path.toFile());if(image==null)continue;try{var bitmap=new BinaryBitmap(new HybridBinarizer(new BufferedImageLuminanceSource(image)));var codes=new GenericMultipleBarcodeReader(new MultiFormatReader()).decodeMultiple(bitmap);for(var code:codes)result.put(code.getText());}catch(NotFoundException ignored){}}return new JSONObject().put("message",result).toString();}
}
